<?php
declare(strict_types=1);namespace Vendi\Inventory;use PDO;use RuntimeException;
final class TransferService{public function __construct(private PDO $db){}
 public function create(int$b,int$from,int$to,int$u,array$items,?string$notes=null):int{if($from===$to)throw new RuntimeException('Origen y destino deben ser distintos.');if(!$items)throw new RuntimeException('Agrega mercancía.');$this->db->beginTransaction();try{$q=$this->db->prepare("INSERT INTO stock_transfers(business_id,from_branch_id,to_branch_id,status,created_by,notes,created_at) VALUES(?,?,?,'draft',?,?,NOW())");$q->execute([$b,$from,$to,$u,$notes]);$id=(int)$this->db->lastInsertId();foreach($items as$x){$qty=(float)$x['quantity_base'];if($qty<=0)continue;$this->db->prepare("INSERT INTO stock_transfer_items(transfer_id,product_id,presentation_id,variant_id,qty_presentation,qty_base,lot_id,lot_number,expires_at,serial_id) VALUES(?,?,?,?,?,?,?,?,?,?)")->execute([$id,(int)$x['product_id'],$x['presentation_id']??null,$x['variant_id']??null,$x['quantity_presentation']??$qty,$qty,$x['lot_id']??null,$x['lot_number']??null,$x['expires_at']??null,$x['serial_id']??null]);}$this->db->commit();return$id;}catch(\Throwable$e){$this->db->rollBack();throw$e;}}
 public function send(int$b,int$id,int$u):void{$this->db->beginTransaction();try{$t=$this->lock($b,$id);if($t['status']!=='draft')throw new RuntimeException('La transferencia ya fue procesada.');foreach($this->items($id) as$x){$qty=(float)$x['qty_base'];$q=$this->db->prepare("SELECT quantity FROM inventory WHERE branch_id=? AND product_id=? FOR UPDATE");$q->execute([$t['from_branch_id'],$x['product_id']]);if((float)($q->fetchColumn()?:0)<$qty)throw new RuntimeException('Existencia insuficiente para enviar.');$this->db->prepare("UPDATE inventory SET quantity=quantity-? WHERE branch_id=? AND product_id=?")->execute([$qty,$t['from_branch_id'],$x['product_id']]);if($x['variant_id']){$v=$this->db->prepare("UPDATE variant_inventory SET quantity=quantity-? WHERE branch_id=? AND variant_id=? AND quantity>=?");$v->execute([$qty,$t['from_branch_id'],$x['variant_id'],$qty]);if($v->rowCount()!==1)throw new RuntimeException('Existencia insuficiente de variante.');}if($x['lot_id']){$l=$this->db->prepare("UPDATE inventory_lots SET qty_base=qty_base-? WHERE id=? AND branch_id=? AND qty_base>=?");$l->execute([$qty,$x['lot_id'],$t['from_branch_id'],$qty]);if($l->rowCount()!==1)throw new RuntimeException('Existencia insuficiente del lote.');}if($x['serial_id']){$s=$this->db->prepare("UPDATE inventory_serials SET status='transit' WHERE id=? AND branch_id=? AND status='available'");$s->execute([$x['serial_id'],$t['from_branch_id']]);if($s->rowCount()!==1)throw new RuntimeException('Serie no disponible.');}$this->move($b,(int)$t['from_branch_id'],(int)$x['product_id'],$x['variant_id']?(int)$x['variant_id']:null,-$qty,$id,$u);}$this->db->prepare("UPDATE stock_transfers SET status='sent' WHERE id=?")->execute([$id]);$this->db->commit();}catch(\Throwable$e){$this->db->rollBack();throw$e;}}
 public function receive(int$b,int$id,int$u):void{$this->db->beginTransaction();try{$t=$this->lock($b,$id);if($t['status']!=='sent')throw new RuntimeException('La transferencia no está en tránsito.');foreach($this->items($id) as$x){$qty=(float)$x['qty_base'];$this->db->prepare("INSERT INTO inventory(branch_id,product_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)")->execute([$t['to_branch_id'],$x['product_id'],$qty]);if($x['variant_id'])$this->db->prepare("INSERT INTO variant_inventory(branch_id,variant_id,quantity,reserved) VALUES(?,?,?,0) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)")->execute([$t['to_branch_id'],$x['variant_id'],$qty]);if($x['lot_id'])$this->db->prepare("INSERT INTO inventory_lots(business_id,branch_id,product_id,lot_number,expires_at,qty_base) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE qty_base=qty_base+VALUES(qty_base),expires_at=COALESCE(VALUES(expires_at),expires_at)")->execute([$b,$t['to_branch_id'],$x['product_id'],$x['lot_number'],$x['expires_at'],$qty]);if($x['serial_id'])$this->db->prepare("UPDATE inventory_serials SET status='available',branch_id=? WHERE id=? AND status='transit'")->execute([$t['to_branch_id'],$x['serial_id']]);$this->move($b,(int)$t['to_branch_id'],(int)$x['product_id'],$x['variant_id']?(int)$x['variant_id']:null,$qty,$id,$u);}$this->db->prepare("UPDATE stock_transfers SET status='received' WHERE id=?")->execute([$id]);$this->db->commit();}catch(\Throwable$e){$this->db->rollBack();throw$e;}}
 private function lock(int$b,int$id):array{$q=$this->db->prepare("SELECT * FROM stock_transfers WHERE id=? AND business_id=? FOR UPDATE");$q->execute([$id,$b]);$r=$q->fetch();if(!$r)throw new RuntimeException('Transferencia no encontrada.');return$r;}private function items(int$id):array{$q=$this->db->prepare("SELECT * FROM stock_transfer_items WHERE transfer_id=?");$q->execute([$id]);return$q->fetchAll();}private function move(int$b,int$branch,int$p,?int$v,float$q,int$r,int$u):void{$s=$this->db->prepare("INSERT INTO stock_movements(business_id,branch_id,product_id,variant_id,type,quantity,reference_type,reference_id,user_id,created_at) VALUES(?,?,?,?, 'transfer',?,'stock_transfer',?,?,NOW())");$s->execute([$b,$branch,$p,$v,$q,$r,$u]);}}
